def smallest_num(list_of_numbers):
    """
    Finds the smallest number in a list.
    """
    if not list_of_numbers:
        return None
    smallest = list_of_numbers[0]
    for number in list_of_numbers:
        if number < smallest:
            smallest = number
    return smallest

