def frequency_lists(list_of_lists):
    """
    Finds the frequency of each element in a flattened list of lists.

    Args:
        list_of_lists: A list of lists of integers.

    Returns:
        A dictionary where the keys are the integers and the values are their frequencies.
    """
    frequencies = {}
    for inner_list in list_of_lists:
        for element in inner_list:
            if element in frequencies:
                frequencies[element] += 1
            else:
                frequencies[element] = 1
    return frequencies

