def search(arr):
    """
    Finds the element that appears only once in a sorted array.
    """
    if not arr:
        return None

    if arr[0] != arr[1]:
        return arr[0]

    if arr[-1] != arr[-2]:
        return arr[-1]

    for i in range(1, len(arr) - 1):
        if arr[i] != arr[i - 1] and arr[i] != arr[i + 1]:
            return arr[i]

    return None

