def amicable_numbers_sum(limit):
    """
    Calculates the sum of all amicable numbers from 1 to a specified number.

    Args:
        limit: The upper limit for finding amicable numbers.

    Returns:
        The sum of all amicable numbers within the limit.
    """
    def sum_divisors(n):
        sum_div = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                sum_div += i
                if i != n // i:
                    sum_div += n // i
        return sum_div

    amicable_sum = 0
    for a in range(1, limit + 1):
        b = sum_divisors(a)
        if a != b and b <= limit and sum_divisors(b) == a:
            amicable_sum += a
    return amicable_sum
